const app = document.querySelector('#app');
const store = createStore();
const state = { selectedProjectId: null, selectedCustomerId: null, viewMode: 'home', guidedDemoIndex: null, guidedDemoTimer: null };
const escapeHtml = (value = '') => String(value).replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
const statusClass = (status) => ({ '확인됨': 'verified', '추정': 'hypothesis', '확인 필요': 'needed', '제안': 'proposal' }[status] ?? 'needed');
const optionLabel = (value) => escapeHtml(value);
function optionSelect(name, label, options, { required = false, value = '', otherName = `${name}Other` } = {}) {
  const isOther = value === '기타' || String(value).startsWith('기타 ·');
  const selected = isOther ? '기타' : value;
  return `<label>${label}<select name="${name}" data-other-select="${name}" ${required ? 'required' : ''}>${options.map((option) => `<option value="${optionLabel(option)}" ${option === selected ? 'selected' : ''}>${optionLabel(option)}</option>`).join('')}</select><input class="other-detail ${isOther ? '' : 'is-hidden'}" name="${otherName}" data-other-for="${name}" value="${isOther ? escapeHtml(String(value).replace(/^기타 ·\s*/, '')) : ''}" placeholder="기타 내용을 입력하세요" ${isOther ? 'required' : ''} /></label>`;
}
function normalizeFormValues(values) {
  for (const key of Object.keys(values)) if (key.endsWith('Other')) values[key.replace(/Other$/, '')] = normalizeOtherValue(values[key.replace(/Other$/, '')], values[key]);
  return values;
}
function itemOptions(customer, includeOther = true) {
  const items = [...new Map((customer.inventory?.items ?? []).map((item) => [item.code, item])).values()];
  const options = items.map((item) => item.code);
  return includeOther && !options.includes('기타') ? [...options, '기타'] : options;
}

function render() {
  const projects = store.listProjects();
  const selectedProject = state.selectedProjectId ? store.getProject(state.selectedProjectId) : null;
  const selectedCustomer = selectedProject ? store.getCustomer(selectedProject.id, state.selectedCustomerId) : null;
  const mainView = selectedProject && selectedCustomer ? (state.viewMode === 'inventory' ? inventoryView(selectedProject, selectedCustomer) : state.viewMode === 'solution' ? solutionView(selectedProject, selectedCustomer) : state.viewMode === 'pre-meeting' ? preMeetingView(selectedProject, selectedCustomer) : state.viewMode === 'research' ? researchView(selectedProject, selectedCustomer) : state.viewMode === 'launch' ? launchView(selectedProject, selectedCustomer) : projectView(selectedProject, selectedCustomer)) : state.viewMode === 'example' ? exampleView() : state.viewMode === 'home' ? homeView(projects) : welcomeView();
  app.innerHTML = `<div class="layout"><aside class="sidebar"><div class="side-title"><span>사업개발 프로젝트</span><button class="icon-button" data-action="new-project">＋</button></div>${projects.length ? projects.map((project) => `<button class="project-item ${project.id === state.selectedProjectId ? 'active' : ''}" data-project="${project.id}"><strong>${escapeHtml(project.companyName)}</strong><small>${project.customers.length}개 고객사 · ${escapeHtml(project.industry || '업종 미지정')}</small></button>`).join('') : '<p class="empty">아직 프로젝트가 없습니다.</p>'}</aside><section class="content">${mainView}</section></div>`;
  bind();
}

function welcomeView() { return `<div class="welcome"><div class="welcome-mark">◎</div><p class="eyebrow">START WITH WHAT YOU KNOW</p><h2>고객을 만나기 전,<br />사업 기회를 구조화하세요.</h2><p>프로젝트 안에서 여러 고객사를 관리하고, 선택한 고객사별로 자료·재고·솔루션 제안을 이어갑니다.</p><div class="welcome-actions"><button class="primary" data-action="new-project">새 사업개발 프로젝트 만들기 <span>→</span></button><button class="secondary" data-action="show-example">사용 예시 보기</button></div><div class="example-strip"><strong>처음 사용한다면</strong><span>고객자료 등록 → 재고·생산 입력 → Solution 제안서 확인</span></div></div>`; }

