function runGuidedDemo() {
  if (state.guidedDemoTimer) clearTimeout(state.guidedDemoTimer);
  startJoysonDemo();
  state.guidedDemoIndex = 0;
  render();
  scheduleGuidedDemo();
}

function scheduleGuidedDemo() {
  if (state.guidedDemoIndex === null) return;
  state.guidedDemoTimer = setTimeout(() => {
    if (state.guidedDemoIndex >= GUIDED_DEMO_STEPS.length - 1) {
      state.guidedDemoTimer = null;
      render();
      return;
    }
    state.guidedDemoIndex += 1;
    render();
    scheduleGuidedDemo();
  }, 1800);
}

function appendGuidedDemo() {
  if (state.viewMode !== 'inventory') return;
  const actionGrid = app.querySelector('.action-grid');
  if (actionGrid && !actionGrid.querySelector('[data-action="run-guided-demo"]')) actionGrid.insertAdjacentHTML('beforeend', '<button class="primary" data-action="run-guided-demo">▶ 자동 실행 데모</button>');
  if (state.guidedDemoIndex === null || app.querySelector('.guided-demo-panel')) return;
  const current = getGuidedDemoStep(state.guidedDemoIndex);
  const panel = document.createElement('section');
  panel.className = 'panel guided-demo-panel';
  panel.innerHTML = `<div class="panel-heading"><div><p class="eyebrow">AUTOMATED WALKTHROUGH · ${current.number}/05</p><h3>시스템 자동 실행 데모</h3><p class="muted">실제 데이터를 변경하지 않고 화면의 계산 순서를 자동으로 보여줍니다.</p></div><button class="secondary" data-action="close-guided-demo">데모 닫기</button></div><div class="guided-progress">${GUIDED_DEMO_STEPS.map((step, index) => `<div class="guided-step ${index < state.guidedDemoIndex ? 'done' : index === state.guidedDemoIndex ? 'active' : ''}"><span>${step.number}</span><strong>${step.title}</strong></div>`).join('')}</div><div class="guided-current"><span class="guided-icon">▶</span><div><strong>${current.title}</strong><p>${current.action}</p><small>결과 · ${current.result}</small></div></div>`;
  app.querySelector('.content')?.append(panel);
}

function openProjectModule(viewMode) {
  const project = store.listProjects()[0];
  if (!project) { modal('project'); return; }
  state.selectedProjectId = project.id;
  state.selectedCustomerId = project.customers[0]?.id ?? null;
  state.viewMode = viewMode;
  render();
}

function appendCalculationGuide() {
  if (state.viewMode !== 'inventory' || app.querySelector('.calculation-guide')) return;
  const guide = document.createElement('section');
  guide.className = 'panel calculation-guide';
  guide.innerHTML = '<div class="panel-heading"><div><p class="eyebrow">HOW THE CALCULATION WORKS</p><h3>재고관리 계산방법과 상하 관계</h3></div><span class="status verified">산식 공개</span></div><div class="calculation-flow"><div><b>1. 생산계획</b><span>완제품·생산일·생산수량</span></div><i>→</i><div><b>2. BOM 전개</b><span>완제품 1개당 부품 소요량</span></div><i>→</i><div><b>3. 자재소요</b><span>생산수량 × BOM 소요량</span></div><i>→</i><div><b>4. 예상재고</b><span>현재고 + 입고 − 소요량</span></div><i>→</i><div><b>5. 위험판정</b><span>안전재고·발주잔량과 비교</span></div></div><div class="formula-grid"><div><strong>자재 필요량</strong><span>생산계획 수량 × 제품 1개당 BOM 소요량</span></div><div><strong>예상 재고</strong><span>기초 재고 + 입고·생산완료 − 출고·생산투입·폐기</span></div><div><strong>순부족량</strong><span>필요량 + 안전재고 − 예상재고 − 발주잔량</span></div><div><strong>생산중단 위험</strong><span>예상 재고가 0 미만이거나 안전재고를 하회하는 경우</span></div></div><p class="muted calculation-note">상위 관계는 생산계획 → 완제품 → BOM → 부품 → 재고거래·발주·입고 → 예상재고 → 위험판정 순서입니다. 하위 부품의 부족량이 상위 완제품 생산 가능 여부에 영향을 줍니다.</p>';
  app.querySelector('.content')?.append(guide);
}

function bind() {
  appendGuidedDemo();
  appendCalculationGuide();
  app.querySelectorAll('[data-other-select]').forEach((select) => {
    const syncOtherField = () => {
      const detail = app.querySelector(`[data-other-for="${select.name}"]`);
      if (!detail) return;
      const visible = select.value === '기타';
      detail.classList.toggle('is-hidden', !visible);
      detail.required = visible;
      if (!visible) detail.value = '';
    };
    select.addEventListener('change', syncOtherField);
    syncOtherField();
  });
  app.querySelectorAll('[data-project]').forEach((button) => button.addEventListener('click', () => { state.selectedProjectId = button.dataset.project; const project = store.getProject(state.selectedProjectId); state.selectedCustomerId = project.customers[0].id; state.viewMode = 'analysis'; render(); }));
  app.querySelectorAll('[data-customer-select]').forEach((select) => select.addEventListener('change', () => { state.selectedCustomerId = select.value; state.viewMode = state.viewMode === 'inventory' ? 'inventory' : 'analysis'; render(); }));
  app.querySelectorAll('[data-action="new-project"]').forEach((button) => button.addEventListener('click', () => modal('project')));
  app.querySelectorAll('[data-action="show-example"]').forEach((button) => button.addEventListener('click', () => { state.viewMode = 'example'; render(); }));
  app.querySelectorAll('[data-action="start-demo"]').forEach((button) => button.addEventListener('click', startDemo));
  app.querySelectorAll('[data-action="open-inventory-demo"]').forEach((button) => button.addEventListener('click', startJoysonDemo));
  app.querySelectorAll('[data-action="run-guided-demo"]').forEach((button) => button.addEventListener('click', runGuidedDemo));
  app.querySelectorAll('[data-action="close-guided-demo"]').forEach((button) => button.addEventListener('click', () => { if (state.guidedDemoTimer) clearTimeout(state.guidedDemoTimer); state.guidedDemoTimer = null; state.guidedDemoIndex = null; render(); }));
  app.querySelectorAll('[data-action="back-welcome"]').forEach((button) => button.addEventListener('click', () => { state.viewMode = 'analysis'; render(); }));
  app.querySelectorAll('[data-action="home"]').forEach((button) => button.addEventListener('click', () => { state.viewMode = 'home'; render(); }));
  app.querySelectorAll('[data-action="open-analysis"]').forEach((button) => button.addEventListener('click', () => openProjectModule('analysis')));
  app.querySelectorAll('[data-action="pre-meeting"]').forEach((button) => button.addEventListener('click', () => openProjectModule('pre-meeting')));
  app.querySelectorAll('[data-action="research"]').forEach((button) => button.addEventListener('click', () => openProjectModule('research')));
  app.querySelectorAll('[data-action="launch"]').forEach((button) => button.addEventListener('click', () => openProjectModule('launch')));
  app.querySelectorAll('[data-action="open-inventory"]').forEach((button) => button.addEventListener('click', () => { const projects = store.listProjects(); if (projects.length) { state.selectedProjectId = projects[0].id; state.selectedCustomerId = projects[0].customers[0].id; state.viewMode = 'inventory'; render(); } }));
  app.querySelectorAll('[data-action="open-solution"]').forEach((button) => button.addEventListener('click', () => { const projects = store.listProjects(); if (projects.length) { state.selectedProjectId = projects[0].id; state.selectedCustomerId = projects[0].customers[0].id; state.viewMode = 'solution'; render(); } }));
  app.querySelectorAll('[data-action="new-customer"]').forEach((button) => button.addEventListener('click', () => modal('customer')));
  app.querySelectorAll('[data-action="business-case"]').forEach((button) => button.addEventListener('click', () => { const project = store.getProject(state.selectedProjectId); const customer = store.getCustomer(project.id, state.selectedCustomerId); state.roi = customer.roi; state.poc = customer.poc; modal('business-case'); }));
  app.querySelectorAll('[data-action="material"]').forEach((button) => button.addEventListener('click', () => modal('material')));
  app.querySelectorAll('[data-action="next-step"]').forEach((button) => button.addEventListener('click', () => nextStepModal(button)));
  app.querySelectorAll('[data-action="proceed-next-step"]').forEach((button) => button.addEventListener('click', () => { button.closest('.modal-backdrop')?.remove(); if (button.dataset.nextAction === 'material') modal('material'); else { const project = store.getProject(state.selectedProjectId); const customer = store.getCustomer(project.id, state.selectedCustomerId); state.roi = customer.roi; state.poc = customer.poc; modal('business-case'); } }));
  app.querySelectorAll('[data-action="inventory"]').forEach((button) => button.addEventListener('click', () => { state.viewMode = 'inventory'; render(); }));
  app.querySelectorAll('[data-action="solution"]').forEach((button) => button.addEventListener('click', () => { state.viewMode = 'solution'; render(); }));
  app.querySelectorAll('[data-action="back-analysis"]').forEach((button) => button.addEventListener('click', () => { state.viewMode = 'analysis'; render(); }));
  app.querySelectorAll('[data-action="add-inventory"]').forEach((button) => button.addEventListener('click', () => inventoryModal('item')));
  app.querySelectorAll('[data-action="add-transaction"]').forEach((button) => button.addEventListener('click', () => inventoryModal('transaction')));
  app.querySelectorAll('[data-action="add-production-plan"]').forEach((button) => button.addEventListener('click', () => inventoryModal('production')));
  app.querySelectorAll('[data-action="add-bom"]').forEach((button) => button.addEventListener('click', () => inventoryModal('bom')));
  app.querySelectorAll('[data-action="add-order"]').forEach((button) => button.addEventListener('click', () => inventoryModal('order')));
  app.querySelectorAll('[data-action="add-receipt"]').forEach((button) => button.addEventListener('click', () => inventoryModal('receipt')));
  app.querySelectorAll('[data-action="close"]').forEach((button) => button.addEventListener('click', () => button.closest('.modal-backdrop').remove()));
  app.querySelectorAll('[data-action="analyze"]').forEach((button) => button.addEventListener('click', () => { const project = store.getProject(state.selectedProjectId); const customer = store.getCustomer(project.id, state.selectedCustomerId); const retained = customer.results.filter((item) => item.sourceType === '미팅 기록' || item.sourceType === '현장 메모'); store.saveResults(project.id, customer.id, [...analyzePreContact(customer), ...retained]); render(); }));
  app.querySelectorAll('[data-form="project"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); const project = store.createProject(normalizeFormValues(Object.fromEntries(new FormData(form)))); state.selectedProjectId = project.id; state.selectedCustomerId = project.customers[0].id; state.viewMode = 'analysis'; render(); }));
  app.querySelectorAll('[data-form="customer"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); const customer = store.createCustomer(state.selectedProjectId, normalizeFormValues(Object.fromEntries(new FormData(form)))); state.selectedCustomerId = customer.id; render(); }));
  app.querySelectorAll('[data-form="business-case"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); const values = Object.fromEntries(new FormData(form)); const roi = calculateRoi(values); const poc = { targetProcess: values.targetProcess.trim(), scope: values.scope.trim(), successMetric: values.successMetric.trim(), duration: values.duration.trim() }; store.saveBusinessCase(state.selectedProjectId, state.selectedCustomerId, { roi, poc }); state.roi = null; state.poc = null; render(); }));
  app.querySelectorAll('[data-form="material"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); const input = normalizeFormValues(Object.fromEntries(new FormData(form))); const project = store.addSourceMaterial(state.selectedProjectId, state.selectedCustomerId, input); const customer = store.getCustomer(project.id, state.selectedCustomerId); const material = customer.materials.at(-1); const results = input.sourceType === '현장 메모' ? analyzeFieldVisit({ ...customer, material }) : input.sourceType === '미팅 기록' ? analyzeMeeting({ ...customer, material }) : analyzePreContact({ ...customer, materials: [material] }); store.appendResults(project.id, customer.id, results); render(); }));
  app.querySelectorAll('[data-form="inventory-item"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); store.addInventoryItem(state.selectedProjectId, state.selectedCustomerId, normalizeFormValues(Object.fromEntries(new FormData(form)))); render(); }));
  app.querySelectorAll('[data-form="inventory-transaction"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); store.recordInventoryTransaction(state.selectedProjectId, state.selectedCustomerId, normalizeFormValues(Object.fromEntries(new FormData(form)))); render(); }));
  app.querySelectorAll('[data-form="production-plan"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); store.addProductionPlan(state.selectedProjectId, state.selectedCustomerId, normalizeFormValues(Object.fromEntries(new FormData(form)))); render(); }));
  app.querySelectorAll('[data-form="bom-line"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); store.addBomLine(state.selectedProjectId, state.selectedCustomerId, normalizeFormValues(Object.fromEntries(new FormData(form)))); render(); }));
  app.querySelectorAll('[data-form="supplier-order"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); store.addSupplierOrder(state.selectedProjectId, state.selectedCustomerId, normalizeFormValues(Object.fromEntries(new FormData(form)))); render(); }));
  app.querySelectorAll('[data-form="supplier-receipt"]').forEach((form) => form.addEventListener('submit', (event) => { event.preventDefault(); store.recordSupplierReceipt(state.selectedProjectId, state.selectedCustomerId, normalizeFormValues(Object.fromEntries(new FormData(form)))); render(); }));
}

render();
